import * as fs from 'fs';
import * as path from 'path';
import { spawn } from 'child_process';

// MCP Demo for OpenClaw Claude Code Skill
// This demo shows MCP server setup, tool verification, and state persistence

interface McpServerConfig {
  command: string;
  args: string[];
  status?: string;
}

interface McpConfig {
  mcpServers: Record<string, McpServerConfig>;
}

interface PersistStore {
  count: number;
  items: string[];
  _hasHydrated: boolean;
}

// State persistence using JSON file (simulating indexedDBStorage)
const PERSIST_FILE = path.join(process.cwd(), 'mcp_persist.json');

function createPersistStore<T>(initialState: T, storeName: string) {
  const storePath = path.join(process.cwd(), `${storeName}.json`);

  let state: T & { _hasHydrated: boolean } = { ...initialState, _hasHydrated: false };

  // Try to load persisted state
  try {
    if (fs.existsSync(storePath)) {
      const data = JSON.parse(fs.readFileSync(storePath, 'utf-8'));
      state = { ...initialState, ...data, _hasHydrated: true };
      console.log(`State restored from ${storeName}`);
    }
  } catch (e) {
    console.log(`Starting fresh for ${storeName}`);
  }

  const save = () => {
    fs.writeFileSync(storePath, JSON.stringify(state, null, 2));
  };

  return {
    getState: () => state,
    setState: (newState: Partial<T>) => {
      state = { ...state, ...newState };
      save();
    },
    increment: () => {
      state = { ...state, count: (state as any).count + 1 };
      save();
    },
    addItem: (item: string) => {
      state = { ...state, items: [...(state as any).items, item] };
      save();
    },
    isHydrated: () => (state as any)._hasHydrated
  };
}

// MCP System simulation
class McpSystem {
  private servers: Map<string, McpServerConfig> = new Map();
  private activeServers: Set<string> = new Set();
  private tools: Map<string, string[]> = new Map();

  setConfigPath(configPath: string) {
    const configData = fs.readFileSync(configPath, 'utf-8');
    const config: McpConfig = JSON.parse(configData);

    for (const [id, serverConfig] of Object.entries(config.mcpServers)) {
      this.servers.set(id, serverConfig);
      console.log(`Configured server: ${id}`);
    }
  }

  async initializeMcpSystem() {
    console.log('\n=== Initializing MCP System ===');

    for (const [id, config] of this.servers) {
      if (config.status === 'active') {
        await this.startServer(id, config);
      }
    }
  }

  async startServer(id: string, config: McpServerConfig) {
    console.log(`\nStarting server: ${id}`);
    console.log(`  Command: ${config.command}`);
    console.log(`  Args: ${config.args.join(' ')}`);

    return new Promise<void>((resolve) => {
      const proc = spawn(config.command, config.args, {
        stdio: ['pipe', 'pipe', 'pipe']
      });

      proc.stdout?.on('data', (data) => {
        console.log(`[${id}] ${data.toString().trim()}`);
      });

      proc.stderr?.on('data', (data) => {
        const err = data.toString().trim();
        if (!err.includes('npm')) {
          console.error(`[${id}] Error: ${err}`);
        }
      });

      // Simulate server startup
      setTimeout(() => {
        this.activeServers.add(id);
        // Simulate available tools for filesystem server
        this.tools.set(id, [
          'read_file',
          'write_file', 
          'list_directory',
          'search_files',
          'get_file_info'
        ]);
        console.log(`Server ${id} started successfully`);
        resolve();
      }, 2000);
    });
  }

  getAllTools(): Map<string, string[]> {
    return new Map(this.tools);
  }

  getClientsStatus(): Record<string, string> {
    const status: Record<string, string> = {};
    for (const [id, config] of this.servers) {
      status[id] = this.activeServers.has(id) ? 'active' : 'inactive';
    }
    return status;
  }

  getActiveServerIds(): string[] {
    return Array.from(this.activeServers);
  }

  getTotalToolCount(): number {
    let count = 0;
    for (const tools of this.tools.values()) {
      count += tools.length;
    }
    return count;
  }
}

async function main() {
  console.log('='.repeat(50));
  console.log('OpenClaw MCP Demo');
  console.log('='.repeat(50));

  const mcpSystem = new McpSystem();

  // 1. Set config path
  console.log('\n--- Setting config path ---');
  mcpSystem.setConfigPath('./mcp_config.json');

  // 2. Get tools BEFORE initialization
  console.log('\n--- Tools BEFORE initialization ---');
  const toolsBefore = mcpSystem.getAllTools();
  console.log(`Server count: ${toolsBefore.size}`);
  console.log(`Total tools: ${mcpSystem.getTotalToolCount()}`);

  // 3. Initialize MCP system
  await mcpSystem.initializeMcpSystem();

  // 4. Get tools AFTER initialization
  console.log('\n--- Tools AFTER initialization ---');
  const toolsAfter = mcpSystem.getAllTools();
  console.log(`Server count: ${toolsAfter.size}`);

  for (const [serverId, toolList] of toolsAfter) {
    console.log(`\nServer: ${serverId}`);
    console.log(`  Tools: ${toolList.join(', ')}`);
  }

  // 5. State persistence demo
  console.log('\n--- State Persistence Demo ---');
  const persistStore = createPersistStore(
    { count: 0, items: [] },
    'mcp_state'
  );

  console.log(`Hydrated: ${persistStore.isHydrated()}`);

  // Write one counter value and one item
  const currentCount = (persistStore.getState() as PersistStore).count;
  persistStore.setState({ count: currentCount + 1 });
  persistStore.addItem('demo-item-' + Date.now());

  const state = persistStore.getState() as PersistStore;
  console.log(`Counter value: ${state.count}`);
  console.log(`Items: ${JSON.stringify(state.items)}`);

  // 6. Generate output summary
  console.log('\n--- Generating Output Summary ---');
  const activeServers = mcpSystem.getActiveServerIds();
  const totalTools = mcpSystem.getTotalToolCount();
  const status = mcpSystem.getClientsStatus();

  const summary = {
    timestamp: new Date().toISOString(),
    activeServerIds: activeServers,
    totalToolCount: totalTools,
    serverStatus: status,
    toolsByServer: Object.fromEntries(toolsAfter),
    persistenceDemo: {
      counterValue: state.count,
      items: state.items,
      hydrated: state._hasHydrated
    }
  };

  const outputPath = path.join(process.cwd(), 'output', 'mcp_summary.json');
  fs.writeFileSync(outputPath, JSON.stringify(summary, null, 2));
  console.log(`Summary written to: ${outputPath}`);

  // Also create a human-readable summary
  const readableSummary = [
    'MCP Demo Summary',
    '='.repeat(30),
    `Active Server IDs: ${activeServers.join(', ') || 'none'}`,
    `Total Tool Count: ${totalTools}`,
    `\nServer Status:`,
    ...Object.entries(status).map(([k, v]) => `  - ${k}: ${v}`),
    `\nPersistence Demo:`,
    `  - Counter: ${state.count}`,
    `  - Items: ${state.items.join(', ') || 'none'}`,
    `  - Hydrated: ${state._hasHydrated}`
  ].join('\n');

  const readablePath = path.join(process.cwd(), 'output', 'mcp_summary.txt');
  fs.writeFileSync(readablePath, readableSummary);
  console.log(`Readable summary written to: ${readablePath}`);

  console.log('\n' + '='.repeat(50));
  console.log('Demo Complete!');
  console.log('='.repeat(50));

  // Cleanup: kill the spawned processes
  process.exit(0);
}

